const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Alvord Desert basin geometry (approximate bounds)
  const alvordDesert = ee.Geometry.Polygon([
    [-118.7, 42.7],
    [-118.3, 42.7],
    [-118.3, 42.3],
    [-118.7, 42.3],
    [-118.7, 42.7]
  ]);

  const targetDate = '2025-06-29';
  const dateRange = 3; // days buffer

  // 2. Try Sentinel-2 first
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(alvordDesert)
    .filterDate(ee.Date(targetDate).advance(-dateRange, 'day'),
                ee.Date(targetDate).advance(dateRange, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  let collectionSize = await collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  // Fallback to Landsat-9 if no Sentinel-2
  if (collectionSize === 0) {
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(alvordDesert)
      .filterDate(ee.Date(targetDate).advance(-dateRange, 'day'),
                  ee.Date(targetDate).advance(dateRange, 'day'));

    collectionSize = await collection.size().getInfo();
    console.log(`Landsat-9 images found: ${collectionSize}`);
  }

  if (collectionSize === 0) {
    console.log('No images found for the date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Process imagery
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  const masked = collection.map(maskS2Clouds);
  const composite = masked.median();

  // Calculate NDWI (Green - NIR) / (Green + NIR)
  const ndwi = composite.normalizedDifference(['B3', 'B8']).rename('NDWI');

  // 4. Check for valid pixels
  const pixelCount = await ndwi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: alvordDesert,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Valid pixels after masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Detect water (NDWI > 0)
  const waterMask = ndwi.gt(0);
  const waterPixels = await waterMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: alvordDesert,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Water pixels detected: ${waterPixels}`);

  if (waterPixels === null || waterPixels === undefined) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (waterPixels > 0) {
    console.log('Surface water present.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No surface water detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
